/// Why a crystal tear is banned.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TearBan {
    /// Named by the ruleset.
    Named,
    /// Raises an attribute.
    Stat,
    /// Raises damage dealt.
    Damage,
    /// Restores HP.
    Heal,
}

